  errorElement.setAttribute('hidden', '');

  console.log('Form submitted: User agreed to terms');
});

checkbox.addEventListener('change', () => {
  if (checkbox.checked) {
    checkbox.setAttribute('aria-invalid', 'false');
    errorElement.setAttribute('hidden', '');
  }
});

